// Sound + haptics. All audio is generated by scripts/gen-sounds.ts. Every call is
// fire-and-forget and safe to fail (web autoplay rules, no audio device, tests).
import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from "expo-audio";
import * as Haptics from "expo-haptics";

const SRC = {
  theme: require("../assets/sounds/theme.wav"),
  wind: require("../assets/sounds/wind.wav"),
  rain: require("../assets/sounds/rain.wav"),
  thunder: require("../assets/sounds/thunder.wav"),
  build: require("../assets/sounds/build.wav"),
  hit: require("../assets/sounds/hit.wav"),
  miss: require("../assets/sounds/miss.wav"),
  pass: require("../assets/sounds/pass.wav"),
  perfect: require("../assets/sounds/perfect.wav"),
  click: require("../assets/sounds/click.wav"),
} as const;
export type SoundName = keyof typeof SRC;

const prefs = { sound: true, music: true, haptics: true };
const players: Partial<Record<SoundName, AudioPlayer>> = {};
let modeSet = false;

function player(name: SoundName): AudioPlayer | null {
  try {
    if (!modeSet) { modeSet = true; void setAudioModeAsync({ playsInSilentMode: false }).catch(() => {}); }
    return (players[name] ??= createAudioPlayer(SRC[name]));
  } catch {
    return null;
  }
}

const safe = (f: () => void) => { try { f(); } catch { /* audio is optional */ } };

export const sound = {
  configure(p: { sound: boolean; music: boolean; haptics: boolean }) {
    Object.assign(prefs, p);
    if (!p.music) sound.stopMusic();
    if (!p.sound) sound.ambience(0, 0);
  },
  music() {
    if (!prefs.music) return;
    const t = player("theme");
    safe(() => { if (!t) return; t.loop = true; t.volume = 0.35; if (!t.playing) t.play(); });
  },
  stopMusic() {
    safe(() => players.theme?.pause());
  },
  /** Ambient loops, 0..1 each. Wind and rain follow the playback weather. */
  ambience(wind: number, rain: number) {
    for (const [name, v] of [["wind", wind], ["rain", rain]] as const) {
      const on = prefs.sound && v > 0.02;
      if (!on && !players[name]) continue;
      const p = player(name);
      safe(() => {
        if (!p) return;
        p.loop = true;
        p.volume = on ? Math.min(1, v) * 0.6 : 0;
        if (on && !p.playing) p.play();
        if (!on && p.playing) p.pause();
      });
    }
  },
  sfx(name: Exclude<SoundName, "theme" | "wind" | "rain">, volume = 0.8) {
    if (!prefs.sound) return;
    const p = player(name);
    safe(() => { if (!p) return; p.volume = volume; void p.seekTo(0); p.play(); });
  },
  /** Light tap for a reveal; a success buzz for a perfect day. */
  haptic(kind: "reveal" | "perfect" | "miss") {
    if (!prefs.haptics) return;
    safe(() => {
      if (kind === "perfect") void Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success).catch(() => {});
      else if (kind === "miss") void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Heavy).catch(() => {});
      else void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light).catch(() => {});
    });
  },
};
